      "rank": 1,
      "ballot_id": "B035",
      "proposed_laureates": ["Hidetoshi Katori", "Jun Ye"],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed atomic timekeeping and opened precision tests of fundamental physics. Their combination of control and extraordinary measurement precision is a major achievement in atomic physics.",
        "attribution": "Katori and Ye independently developed leading approaches to lattice clocks and drove their experimental realization.",
        "maturity": "The methods have been repeatedly realized and refined across laboratories, with clocks now enabling measurements beyond timekeeping.",
        "uncertainties": ["The division between the two approaches and the broader contributions of clock development would need careful consideration."]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B017",
      "proposed_laureates": ["Immanuel Bloch", "Juan Ignacio Cirac", "Peter Zoller"],
      "assessment": {
        "nobel_worthiness": "Controlled atoms made quantum simulation and information processing experimentally accessible, connecting precise few-particle control to many-body physics.",
        "attribution": "Cirac and Zoller supplied foundational proposals and theory; Bloch established major experimental demonstrations with ultracold atoms.",
        "maturity": "The field has produced sustained experimental progress and independent demonstrations, though programmable quantum simulation continues to evolve.",
        "uncertainties": ["The discovery spans several platforms and contributions, so a three-person selection risks omitting important experimental work."]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B012",
      "proposed_laureates": ["Alexei Kitaev", "Andrew Steane", "Peter W. Shor"],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed that quantum information can in principle be protected against noise, a conceptual advance with deep consequences for quantum physics and computation.",
        "attribution": "Shor and Steane developed influential early codes; Kitaev's surface-code work connected fault tolerance to topological ideas and practical architectures.",
        "maturity": "The theory is established and experimental demonstrations of error correction have advanced substantially, but large-scale fault-tolerant operation remains unrealized.",
        "uncertainties": ["The credit is distributed across several foundational ideas, and the ultimate physical reach of fault-tolerant quantum computing remains open."]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B018",
      "proposed_laureates": ["Carlton M. Caves", "H. Jeff Kimble", "Roman Schnabel"],
      "assessment": {
        "nobel_worthiness": "Squeezed light overcomes quantum measurement noise limits and has become a powerful way to improve precision interferometry, including gravitational-wave detection.",
        "attribution": "Caves established the quantum-noise framework; Kimble advanced optical squeezing and its interferometric use; Schnabel contributed to robust squeezed-light sources and applications.",
        "maturity": "The effect is well established, repeatedly demonstrated, and used in operating precision instruments.",
        "uncertainties": ["Several theorists and experimental groups contributed to the path from the original idea to routine use."]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B040",
      "proposed_laureates": ["David E. Pritchard", "Jürgen Mlynek", "Mark A. Kasevich"],
      "assessment": {
        "nobel_worthiness": "Atom interferometry brought coherent matter waves into precision measurement and enabled tests of gravity and fundamental constants with a new level of control.",
        "attribution": "These researchers made important early contributions to atom-optical methods and interferometric measurements, though the field grew through multiple groups.",
        "maturity": "The technique has been replicated and extended across many experiments, with continuing gains in precision and applications.",
        "uncertainties": ["The broad scope of the field makes it difficult to identify a small set of people who capture its foundational contributions."]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B032",
      "proposed_laureates": ["Peter F. Moulton", "Wilson Sibbett"],
      "assessment": {
        "nobel_worthiness": "Titanium-sapphire lasers and Kerr-lens mode-locking enabled compact, widely tunable ultrafast pulses that helped make time-resolved atomic physics possible.",
        "attribution": "Moulton developed the key laser material and system; Sibbett helped establish and demonstrate Kerr-lens mode-locking.",
        "maturity": "The technologies have been reproduced, refined, and used broadly for decades.",
        "uncertainties": ["The advances were part of a wider development of ultrafast laser techniques, complicating the boundary of the prize-worthy contribution."]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B039",
      "proposed_laureates": ["Heino Falcke", "J. Anton Zensus", "Sheperd S. Doeleman"],
      "assessment": {
        "nobel_worthiness": "Horizon-scale imaging made the immediate environment of black holes observable and provided a striking test of strong-gravity astrophysics.",
        "attribution": "Falcke helped develop the imaging concept, Zensus contributed major expertise in very-long-baseline interferometry, and Doeleman led key observational efforts.",
        "maturity": "The first images were followed by additional results and independent analysis, although the observations remain technically demanding.",
        "uncertainties": ["The images came from a large international collaboration, and interpretation depends on calibration and modeling."]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B002",
      "proposed_laureates": ["Allan H. MacDonald", "Pablo Jarillo-Herrero", "Rafi Bistritzer"],
      "assessment": {
        "nobel_worthiness": "Magic-angle twisted bilayer graphene revealed that moiré structures can generate strongly correlated electronic phases in a tunable solid-state system.",
        "attribution": "Bistritzer and MacDonald predicted the key moiré-band physics; Jarillo-Herrero's group discovered correlated behavior experimentally.",
        "maturity": "The original results prompted extensive follow-up, but the field remains active and the full relation among competing phases is still being resolved.",
        "uncertainties": ["The range and reproducibility of the correlated phases, and the relative roles of interactions and disorder, remain under study."]
      }
    }
  ]
